"""Human-reviewed benchmark interpretation; no detector changes."""
from pathlib import Path
import json
from run_confirmed import OUT,ROOT


def main():
    rs=json.loads((OUT/'results.json').read_text());summary=json.loads((OUT/'summary.json').read_text())
    lines=['# V3 — результат проверки на подтверждённой человеком разметке','',
    'Приняты все 10 JSON из Standalone_Torgsoft_Geometry_Lab_V3/confirmed. Проверены SHA идентификаторов, размер изображения, подтверждение каждой линии, автор/дата, структура координат. Исходные JSON сохранены без изменений. Контрольные суммы файлов: confirmed_manifest.json.',
    '', 'Запуск: 4 параллельных процесса по фотографиям. В каждой фотографии три метода получают один и тот же объект линий; controls_sha256 совпадает. Замороженные ранее исходники детектора и методов не менялись. Предыдущие предварительные результаты сохранены в standalone_geometry_v3_stage2.',
    '', '## Преобразования на одинаковых подтверждённых контролях','',
    '| Метод | Построено | Средняя ошибка, px | Макс. среднего по фото, px | Фото с переворотом карты |',
    '|---|---:|---:|---:|---:|']
    for s in summary['methods']:
        lines.append(f'| {s["method"]} | {s["calculated"]}/10 | {s["mean_source_error_px"]} | {s["max_case_mean_px"]} | {s["cases_with_folds"]} |')
    lines+=['',
    'Ошибка — расстояние обратной проекции синей сетки до подтверждённых исходных полилиний, в пикселях исходного фото, внутри наблюдаемой области. Среднее считается по средним каждого снимка. Субпиксельные значения Mesh не означают, что человек или детектор нашли печать с точностью 0,1 px: это соблюдение поданных кусочно-линейных контролей, с погрешностью ручных точек и интерполяции.',
    'Проверка якобиана не выявила переворотов ни у одного из 30 преобразований human_confirmed. У помятого снимка 4eae80… часть поверхности выходит за исходное изображение: source_valid_fraction около 0,994–0,995. Эти невидимые данные не восстановлены.',
    '', '## Автоматическое обнаружение относительно подтверждённой разметки','',
    '| Фото | Подтверждено полных горизонталей | Старые кандидаты | Граф | Пропуски графа, индексы с 0 | Несопоставленные кандидаты графа |',
    '|---|---:|---:|---:|---|---|']
    for r in rs:
        old=r['detector_matches']['legacy_observations']['horizontal'];g=r['detector_matches'].get('physical_graph_auto',{}).get('horizontal')
        lines.append(f'| {r["job"][:10]} | {old["reference"]} | {old["detected"]} | {g["detected"] if g else "отказ"} | {g["missing"] if g else "не оценено"} | {g["false"] if g else "не оценено"} |')
    lines+=['',
    'Сопоставление взаимно однозначное, порог 8 px. «Пропуски/лишние» здесь означают несопоставленные полилинии, а не безусловное заключение об их физическом происхождении: сильно смещённая настоящая граница тоже может не пройти порог. Подробные координаты, парные расстояния, пропуски старого детектора и вертикали — в results.json.',
    'Граф полностью сопоставляет горизонтали только на 4 из 10 development-фото. На остальных есть пропуски или отказ. В этот счёт не включена точность всех вертикалей. Не использовать его как оценку независимой точности.',
    '', '## Чек №575866','',
    'Подтверждено 6 полных горизонталей: верх таблицы, низ двухстрочного заголовка, низ каждого из 3 товаров, низ НДС. Старый детектор выдаёт 14 кандидатов и отказывает из-за пересекающихся кривых. Граф находит 6 сопоставленных горизонталей без лишних; Mesh по подтверждённым линиям удерживает их со средним остатком 0,09 px.',
    'Изображение: cases/2efa41ac6b3d45ca9457e456b5768cd5/human_confirmed_grid_mesh.jpg. Заголовок «Кол-во» остаётся одной ячейкой, лишней товарной строки нет. Это геометрический прогон; OCR количества и итогов заново не запускался.',
    'Выявлен ещё один предел существующего вывода: _dest обрезает изображение по последней полной горизонтали + 16 px. Нижняя ячейка итога 45 936 может быть обрезана. Отдельная геометрия частичного блока итогов пока не включена в выходной размер. Граф также сохраняет ошибочное продолжение некоторых вертикалей за таблицей. Это причины не переносить текущий результат в рабочий OCR.',
    '', '## Ответы и следующий этап','',
    '1. Основная причина неправильного количества строк — детектор на исходном фото: масштабные пороги объединения, примесь текста, выбор края бумаги и фоновых линий. Дополнительно есть ошибка модели преобразования: Perspective не удерживает внутренние изгибы и положения внутренних контролей. Подтверждённые линии позволили это разделить.',
    '2. На этих 10 подтверждённых наборах лучше всего соблюдает контроли Grid Mesh. TPS второй; Perspective заметно хуже на длинных и изогнутых таблицах. Это заключение о геометрии при заданных линиях, не о готовности автоматической системы.',
    '3. Единая модель граф -> обратная карта -> синяя сетка возможна; Mesh уже поддерживает этот принцип. До внедрения нужны полнота детектора, корректные вертикальные наблюдения, геометрия НДС/частичного итога, проверка невидимых участков и независимый контроль.',
    '',
    'Подтверждённые 10 фотографий — development-набор, на котором детектор уже разрабатывался. Они не превращаются в независимый тест после ручного подтверждения. Восемь ранее зафиксированных контрольных фото остаются без подтверждённой разметки. Следующий независимый тест требует разметить именно их и проверить отсутствие повторов физических чеков; новых снимков пока не добавлялось.',
    '', '**Решение: использовать Grid Mesh как основной кандидат геометрии для дальнейших лабораторных испытаний. Готовность к внедрению не объявлять. Рабочий OCR не изменён.**',
    '', 'Воспроизведение:', '```powershell',
    'Standalone_Torgsoft_Geometry_Lab_V3/.venv/Scripts/python.exe Standalone_Torgsoft_Geometry_Lab_V3/run_confirmed.py',
    'Standalone_Torgsoft_Geometry_Lab_V3/.venv/Scripts/python.exe Standalone_Torgsoft_Geometry_Lab_V3/report_confirmed.py',
    '```']
    (OUT/'FINDINGS.md').write_text('\n'.join(lines),encoding='utf-8')
    previous=ROOT/'experiment_outputs/standalone_geometry_v3_stage2/index.html'
    text=previous.read_text(encoding='utf-8');link='<p><strong><a href="../standalone_geometry_v3_confirmed/index.html">Новый прогон: все 10 фотографий подтверждены человеком</a></strong></p>'
    if '../standalone_geometry_v3_confirmed/index.html' not in text:
        previous.write_text(text.replace('<h1>',link+'<h1>',1),encoding='utf-8')
    print('Human-confirmed findings written')


if __name__=='__main__':main()
